{"type":"LibraryCall","library_topic_name":"Data Collector","library_topic_id":"4c19933e4322211006650464dbb8f22d","library_topic_is_template":false,"parameter-mappings":[{"parameter-name":"definition","value":{"type":"String","mode":"script","value":"(function execute() {
 var config = {
 configuration: {"purpose":"{{0}}","inputs":[{"name":"display_user_active_badges","type":"carousel","discoverable":true,"description":"Ask user to select one of displayed badges to take further action \nASK ONE LINE QUESTION as Please select badge to be replaced.","skipMode":"'simple'","skipCondition":"\"\"","helpText":"false","script":"(function(vaVars, vaInputs) {return (function execute() {\n var options = [];\n var items = JSON.parse(vaVars.user_badges_list|| '[]');\n if (items.length === 0) {\n options.push({\n name: 'No Badge',\n value: 'none',\n description: 'No badge found',\n body: 'https://somehost/somepath/somepic1.jpg'\n });\n } else {\n items.forEach(function(it) {\n options.push({\n name: it.name || '',\n value: it.value || '',\n description: it.description || '',\n body: it.body || ''\n });\n });\n }\nreturn options;\n})();\n;})(_taskVaVars[{{4}}], _taskVaInputs[{{5}}])","applicability":"","validation":""},{"name":"ask_reason","type":"choice","discoverable":true,"description":"Ask user the reason for replacement of badge as \nPlease select reason for replacement of selected badge.","skipMode":"'simple'","skipCondition":"\"\"","helpText":"false","choices":[{"value":"lost","label":"Lost"},{"value":"stolen","label":"Stolen"}],"applicability":"","validation":""}],"instructions":"{{1}}","advanced_parameters":"{{2}}","callingTask":"{{3}}","confirm_summary":false,"slots":[{"name":"select_new_badge","type":"carousel","discoverable":true,"description":"ask user to select the new badge","validation":"","script":"(function(vaVars, vaInputs) {return (function execute() {\n\n var baseURL = gs.getProperty('glide.servlet.uri');\n var images = {};\n images['PERMANENT_BADGE'] = baseURL + '/x_aleen_aia_skills.permanentbadge.png';\n images['TEMP_BADGE'] = baseURL + '/x_aleen_aia_skills.visitorbadge.png';\n images['MOBILE_CREDENTIAL'] = baseURL + '/x_aleen_aia_skills.digitalbadge.png';\n\n var options = [];\n var badgeGr = new GlideRecordSecure('x_aleen_snguardian_asset');\n badgeGr.addQuery('status.code','UNASSIGNED');\n badgeGr.addQuery('type.code',vaVars.badge_type);\n badgeGr.addQuery('system',vaVars.badge_system);\n //subsytem , subtype\n badgeGr.setLimit(5);\n badgeGr.query();\n var count=0;\n while(badgeGr.next()){\n if(count<5){\n options.push({\n 'name': badgeGr.getDisplayValue(\"serial\"),\n 'value': badgeGr.getValue(\"sys_id\"),\n 'description': badgeGr.getDisplayValue(\"system.code\") + \" - \" + badgeGr.getDisplayValue(\"status.name\"),\n 'body': images[badgeGr.getDisplayValue(\"type.code\")]\n })\n }\n count++; \n }\n if (count === 0) {\n options.push({\n 'name': 'No badge found',\n 'value': '',\n 'description': 'There are no available badges matching your criteria.',\n 'body': ''\n });\n }\n return options;\n})()\n;})(_taskVaVars[{{6}}], _taskVaInputs[{{7}}])"},{"name":"badge_valid_from","type":"date_time","discoverable":true,"description":"Ask user to select valid from date\n","validation":"","format":"date_time"},{"name":"badge_valid_to","type":"date_time","discoverable":true,"description":"Ask user to select valid to date\n","validation":"","format":"date_time"}],"applicability":"","classificationOverrides":[]}
 };
 return JSON.stringify(config);
